WITH src AS (SELECT *, DATEDIFF(CURRENT_DATE(), hire_date) AS days_since_hire_date FROM employees WHERE LENGTH(email) > 14 AND salary BETWEEN 82000 AND 100000), agg AS (SELECT job_title, ROUND(STDDEV(days_since_hire_date), 2) AS stddev_days_since_hire_date, COUNT(days_since_hire_date) AS days_since_hire_date_count FROM src GROUP BY job_title) SELECT job_title, stddev_days_since_hire_date FROM agg WHERE days_since_hire_date_count >= 6 ORDER BY job_title DESC
